import { StudioProApi } from "@mendix/extensions-api";
import { Knowledgebase } from "../../types/knowledgebase";
import { createStudioProLogger } from "../../config/logger";

export const handleKnowledgebaseChangeValue =
    (
        studioPro: StudioProApi,
        field: keyof Knowledgebase,
        knowledgebase: Knowledgebase,
        setKnowledgebase: React.Dispatch<React.SetStateAction<Knowledgebase>>,
        documentId: string
    ) =>
    async (value: string) => {
        const updatedKnowledgebase = { ...knowledgebase, [field]: value };
        setKnowledgebase(updatedKnowledgebase);
        updateKnowledgebaseDocument(studioPro, updatedKnowledgebase, documentId);
    };

const updateKnowledgebaseDocument = async (
    studioPro: StudioProApi,
    knowledgebase: Knowledgebase,
    documentId: string
) => {
    const logger = createStudioProLogger(studioPro);
    try {
        await studioPro.app.model.customBlobDocuments.updateDocumentContent(documentId, knowledgebase);
    } catch (error) {
        logger.error("Failed to save knowledgebasedocument:", error);
        studioPro.ui.notifications.show({
            title: "Failed to save document",
            message: (error as Error).message,
        });
    }
};
